export const REVIEW_PROFILE_ASSETS: Record<ReviewProfileAssetKey, string> = {
  "code-diff": CODE_DIFF_PROFILE_MARKDOWN,
  "plan": PLAN_PROFILE_MARKDOWN,
  "prose-claim": PROSE_CLAIM_PROFILE_MARKDOWN,
  "spec-design": SPEC_DESIGN_PROFILE_MARKDOWN
}
